"""
Curriculum Schedule for Universal CAPTCHA Generator.

Defines difficulty tiers and progression for training data generation.
All schemas are generated by random sampling from the feature space,
stratified by difficulty level.
"""

import random
from typing import Optional, Dict

from .config import CaptchaSchema, random_schema


# ═══════════════════════════════════════════════════════════
# Difficulty tier definitions
# ═══════════════════════════════════════════════════════════

# Each tier maps to a difficulty range for random feature sampling
DIFFICULTY_TIERS = {
    1: {
        "difficulty_range": (0.0, 0.15),
        "description": "Clean backgrounds, single font, no noise, no distortion",
    },
    2: {
        "difficulty_range": (0.15, 0.35),
        "description": "Simple backgrounds, 2-3 fonts, light noise, slight rotation",
    },
    3: {
        "difficulty_range": (0.35, 0.60),
        "description": "Complex backgrounds, multiple fonts, moderate noise + distortion",
    },
    4: {
        "difficulty_range": (0.60, 0.85),
        "description": "All feature layers active, heavy noise, heavy distortion",
    },
    5: {
        "difficulty_range": (0.80, 1.0),
        "description": "Maximum feature density, full adversarial complexity",
    },
}


class CurriculumScheduler:
    """
    Manages curriculum-based schema selection using difficulty-stratified
    random sampling from the feature space.
    """

    def __init__(
        self,
        tier_distribution: Optional[Dict[int, float]] = None,
    ):
        """
        Args:
            tier_distribution: Dict mapping tier (1-5) to probability weight.
                If None, uses a balanced distribution.
        """
        if tier_distribution is None:
            self.tier_distribution = {1: 0.1, 2: 0.2, 3: 0.3, 4: 0.25, 5: 0.15}
        else:
            self.tier_distribution = tier_distribution

        assert all(1 <= t <= 5 for t in self.tier_distribution), "Tiers must be 1-5"

    def sample_tier(self) -> int:
        """Sample a tier based on the distribution."""
        tiers = list(self.tier_distribution.keys())
        weights = [self.tier_distribution[t] for t in tiers]
        return random.choices(tiers, weights=weights, k=1)[0]

    def get_schema(self, tier: Optional[int] = None) -> CaptchaSchema:
        """
        Get a randomly composed schema for the given tier.

        Args:
            tier: Specific tier (1-5), or None to sample from distribution.

        Returns:
            CaptchaSchema with difficulty sampled from the tier's range.
        """
        if tier is None:
            tier = self.sample_tier()

        tier = max(1, min(5, tier))
        tier_config = DIFFICULTY_TIERS[tier]
        d_min, d_max = tier_config["difficulty_range"]
        difficulty = random.uniform(d_min, d_max)
        return random_schema(difficulty=difficulty)

    def get_progressive_schema(self, progress: float) -> CaptchaSchema:
        """
        Get a schema based on training progress.

        Args:
            progress: Training progress from 0.0 (start) to 1.0 (end).

        Returns:
            CaptchaSchema with difficulty scaled to progress.
        """
        if progress < 0.15:
            tier = 1
        elif progress < 0.35:
            tier = 2
        elif progress < 0.60:
            tier = 3
        elif progress < 0.85:
            tier = 4
        else:
            tier = 5

        return self.get_schema(tier=tier)


# ═══════════════════════════════════════════════════════════
# Distribution presets for common training phases
# ═══════════════════════════════════════════════════════════

def pretraining_distribution() -> Dict[int, float]:
    """Heavy on easy/medium for building basic character recognition."""
    return {1: 0.2, 2: 0.3, 3: 0.25, 4: 0.15, 5: 0.1}


def very_easy_distribution() -> Dict[int, float]:
    """Strongly easy-weighted: minimal hard tiers (learnability lever, not difficulty)."""
    return {1: 0.3, 2: 0.35, 3: 0.25, 4: 0.07, 5: 0.03}


def balanced_distribution() -> Dict[int, float]:
    """Equal representation across all difficulty tiers."""
    return {1: 0.2, 2: 0.2, 3: 0.2, 4: 0.2, 5: 0.2}


def adversarial_distribution() -> Dict[int, float]:
    """Heavy on hard/adversarial for robustness training."""
    return {1: 0.05, 2: 0.1, 3: 0.2, 4: 0.35, 5: 0.3}


def hardened_distribution() -> Dict[int, float]:
    """Focus on maximum difficulty with minimal easy examples."""
    return {1: 0.05, 2: 0.05, 3: 0.15, 4: 0.35, 5: 0.4}
